package com.dy.artisan3d.ui.screen.main.article.listimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.PaddingValuesimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.lazy.LazyColumnimport androidx.compose.foundation.lazy.itemsimport androidx.compose.material3.Scaffoldimport androidx.compose.material3.pulltorefresh.PullToRefreshBoximport androidx.compose.material3.pulltorefresh.rememberPullToRefreshStateimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.ui.Modifierimport androidx.compose.ui.unit.dpimport androidx.lifecycle.compose.collectAsStateWithLifecycleimport artisan3d.composeapp.generated.resources.Resimport artisan3d.composeapp.generated.resources.articleimport com.dy.artisan3d.ui.component.ArtisanArticleCardimport com.dy.artisan3d.ui.component.Topbarimport org.jetbrains.compose.resources.stringResource@Composablefun ArticleListContent(    viewModel: ArticleListViewModel,    onArticleClick: (Int) -> Unit,) {    val state by viewModel.uiState.collectAsStateWithLifecycle()    // Pull-to-Refresh holati    val isRefreshing = state.isLoading    val pullRefreshState = rememberPullToRefreshState()    Scaffold(        modifier = Modifier.fillMaxSize(), topBar = {            Topbar(title = stringResource(Res.string.article))        }) { padding ->        PullToRefreshBox(            isRefreshing = isRefreshing,            onRefresh = { viewModel.fetchHomeData(true) },            state = pullRefreshState,            modifier = Modifier.padding(padding).fillMaxSize()        ) {            LazyColumn(                verticalArrangement = Arrangement.spacedBy(12.dp),                modifier = Modifier.fillMaxSize(),                contentPadding = PaddingValues(start = 16.dp, end = 16.dp, bottom = 20.dp)            ) {                items(state.articles) { data ->                    ArtisanArticleCard(data) {                        onArticleClick(data.id)                    }                }            }        }    }}